from pathlib import Path
import shutil,urllib.request
root=Path('/home/user/Desktop/inventory-system');desktop=Path.home()/'Desktop'
browser=shutil.which('chromium') or shutil.which('chromium-browser')
assert browser,'Chromium is required'
launcher=desktop/'Homebox.desktop'
launcher.write_text(f'[Desktop Entry]\nType=Application\nName=Homebox\nComment=Open the normal Homebox inventory interface\nExec={browser} --user-data-dir=/home/user/.config/homebox-browser --new-window http://127.0.0.1:17745\nIcon=web-browser\nTerminal=false\n')
launcher.chmod(0o755)
guide=root/'docs/homebox-access.html'
guide.write_text(r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Connect to Homebox</title><style>body{font:19px/1.65 "Segoe UI",Arial,sans-serif;color:#17384a;background:#edf4f7;margin:0}main{max-width:900px;margin:30px auto;padding:28px;background:white}h1{font-size:38px;line-height:1.2}h2{margin-top:35px}a{color:#245c89}code{overflow-wrap:anywhere}pre{background:#edf4f7;padding:18px;white-space:pre-wrap;overflow-wrap:anywhere}aside{padding:18px;background:#ffedc5;border-left:5px solid #bb830d}li{margin:12px 0}.button{display:inline-block;padding:12px 20px;background:#245c89;color:white;text-decoration:none;border-radius:5px}</style><main><h1>Connect to the normal Homebox</h1><p>The Equipment Terminal is a companion to Homebox. Both use the same native inventory, locations, photos, categories, and maintenance records.</p><h2>On this Pi</h2><ol><li>Open the desktop shortcut <b>Homebox</b>.</li><li>Sign in with your own Homebox email and password. Your kiosk badge is not a Homebox web password.</li><li>Use the normal Homebox pages to manage your inventory. Changes are reflected in the companion after refresh.</li></ol><a class="button" href="http://127.0.0.1:17745">Open Homebox on this Pi</a><p>The Pi address is <code>http://127.0.0.1:17745</code>. This link works on the Pi itself. Homebox works offline; no internet is required for local inventory.</p><aside>The normal Homebox interface does not provide the companion’s touchscreen keyboard. Use a keyboard on the Pi or the laptop route below for text-heavy administration. The companion’s checkout ledger, personal badge controls, and return-note log remain in Equipment Terminal.</aside><h2>On your configured Windows laptop</h2><ol><li>Connect the direct Ethernet cable or join the same Wi-Fi network.</li><li>Open <b>Workshop Editor</b> and keep its connection window open. The launcher forwards both Homebox and the companion.</li><li>In the laptop browser, open <code>http://127.0.0.1:17745</code> and sign in to Homebox.</li><li>Save your changes before disconnecting the launcher.</li></ol><p>On a different Wi-Fi network, the Pi may have a new address. Run <code>hostname -I</code> on the Pi to find it, then supply the current address:</p><pre>powershell -ExecutionPolicy Bypass -File .\Open-Workshop.ps1 -PiAddress NEW_PI_ADDRESS</pre><p>The direct laptop cable uses <b>10.77.0.1</b>. The default Wi-Fi fallback is <b>192.168.1.61</b>. The dedicated cable profile must not be connected to a shared router LAN while it supplies DHCP.</p><h2>Another computer with authorized SSH access</h2><p>Connect to the Pi over an encrypted tunnel. Replace the address with its current network address:</p><pre>ssh -N -L 127.0.0.1:17745:127.0.0.1:17745 user@PI_ADDRESS</pre><p>Keep that terminal open, then visit <code>http://127.0.0.1:17745</code> on that computer. Use your own authorized SSH credentials and verify the Pi host identity. Close the terminal to disconnect.</p><h2>What does not connect automatically?</h2><p>Homebox currently listens only on the Pi’s loopback address. Browsing to <code>http://PI_ADDRESS:17745</code> from another device will not work directly. Use the existing laptop launcher or SSH tunnel. A phone needs a compatible SSH tunnel client or a separately configured access method; Codex phone pairing does not publish Homebox.</p><aside>Homebox web changes do not automatically reconcile borrowed-equipment custody. Complete checkout and return through Equipment Terminal. Before editing equipment involved in an interrupted transaction, review the saved operation to avoid conflicting changes.</aside><p><a href="user-guide/index.html">Full user and administrator guide</a></p><p>Updated October 4, 2026.</p></main></html>''')
help_launcher=desktop/'Homebox Connection Guide.desktop'
help_launcher.write_text('[Desktop Entry]\nType=Application\nName=Homebox Connection Guide\nComment=How to open Homebox on the Pi or another device\nExec=xdg-open /home/user/Desktop/inventory-system/docs/homebox-access.html\nIcon=help-browser\nTerminal=false\n')
help_launcher.chmod(0o755)
assert urllib.request.urlopen('http://127.0.0.1:17745',timeout=8).status==200
print('Homebox responds; desktop application and connection-guide shortcuts installed.')
